<script setup lang="ts">
import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import type { FormInstance, FormRules } from 'element-plus'; import { useAuthStore } from '../stores/auth'
const formRef = ref<FormInstance>(); const router = useRouter(); const auth = useAuthStore(); const form = reactive({ username: '', password: '', confirmPassword: '', nickname: '', email: '', phone: '' })
const rules: FormRules = { username: [{ required: true, message: '请输入用户名', trigger: 'blur' }, { pattern: /^[a-zA-Z0-9_]{4,50}$/, message: '4-50 位字母、数字或下划线', trigger: 'blur' }], password: [{ required: true, message: '请输入密码', trigger: 'blur' }, { min: 8, max: 64, message: '密码长度为 8-64 位', trigger: 'blur' }], confirmPassword: [{ validator: (_r, value, callback) => value === form.password ? callback() : callback(new Error('两次输入的密码不一致')), trigger: 'blur' }], email: [{ type: 'email', message: '邮箱格式不正确', trigger: 'blur' }], phone: [{ pattern: /^$|^1\d{10}$/, message: '手机号格式不正确', trigger: 'blur' }] }
async function submit() { if (!await formRef.value?.validate()) return; const { confirmPassword: _, ...request } = form; await auth.register(request); ElMessage.success('注册成功，已自动登录'); router.replace('/') }
</script>
<template><main class="auth-page register-page"><RouterLink class="auth-brand" to="/"><span class="brand-mark">蓝</span><strong>蓝境</strong></RouterLink><section class="auth-card"><div class="auth-intro"><p class="eyebrow">JOIN THE BLUE</p><h1>从认识开始，<br>成为海洋守护者。</h1><p>注册普通用户账号后，你可以继续申请志愿者身份，参与真实的救助工单流程。</p></div><div class="auth-form"><h2>创建账号</h2><p>已经注册？<RouterLink to="/login">返回登录</RouterLink></p><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="submit"><div class="form-row"><el-form-item label="用户名" prop="username"><el-input v-model="form.username" size="large" /></el-form-item><el-form-item label="昵称（选填）"><el-input v-model="form.nickname" size="large" /></el-form-item></div><div class="form-row"><el-form-item label="密码" prop="password"><el-input v-model="form.password" size="large" type="password" show-password /></el-form-item><el-form-item label="确认密码" prop="confirmPassword"><el-input v-model="form.confirmPassword" size="large" type="password" show-password /></el-form-item></div><el-form-item label="邮箱（选填）" prop="email"><el-input v-model="form.email" size="large" /></el-form-item><el-form-item label="手机号（选填）" prop="phone"><el-input v-model="form.phone" size="large" /></el-form-item><el-button class="auth-submit" type="primary" size="large" native-type="submit" :loading="auth.loading">注册并登录</el-button></el-form></div></section></main></template>
